# normalize: could be dict or list
def norm(d):
    m={}
    if isinstance(d,dict):
        # maybe {task: reward} or {'tasks':[...]}
        if 'tasks' in d: d=d['tasks']
    if isinstance(d,list):
        for x in d:
            t=x.get('task_id') or x.get('task') or x.get('id')
            rw=x.get('reward'); 
            if rw is None: rw=x.get('passed')
            m[t]=rw
    elif isinstance(d,dict):
        for t,v in d.items():
            if isinstance(v,dict): m[t]=v.get('reward',v.get('passed'))
            else: m[t]=v
    return m
