for m in mats.values(): allt|=set(m.keys())
print('rounds parsed:', list(mats.keys()))
for t in sorted(allt):
    row=''.join(str(int(mats[r].get(t,-1))) if mats[r].get(t) is not None and mats[r].get(t)!=-1 else '.' for r in sorted(mats))
    print(f'{t:32} {row}')
