import json
def first_assistant_texts(t, n=2):
    msgs=json.load(open(t+'.messages.json'))
    out=[]
    for m in msgs:
        if m.get('role')=='assistant':
            c=m.get('content')
            if isinstance(c,str): txt=c
            elif isinstance(c,list): txt=' '.join(str(p.get('text','')) for p in c if isinstance(p,dict) and 'text' in p)
            else: txt=''
            if txt.strip(): out.append(txt)
