import json, re, hashlib
def cmds(t):
    msgs=json.load(open(t+'.messages.json')); out=[]
    for m in msgs:
        if m.get('role')=='assistant':
            for p in (m.get('content') if isinstance(m.get('content'),list) else []):
                if isinstance(p,dict) and p.get('type')=='tool_use':
                    out.append(p.get('input',{}).get('command',''))
        for tc in m.get('tool_calls',[]) or []:
            import json as J
            try: a=J.loads(tc.get('function',{}).get('arguments','{}'))
            except: a={}
            if 'command' in a: out.append(a['command'])
    return [c for c in out if c]
for t in ['task_000264_ab8c7253','task_001031_a8f0eb37','task_001818_b251e5ea','task_000958_4bb2b05d']:
    cs=cmds(t)
    # normalize full and prefix-60
    def norm(s): return re.sub(r'\s+',' ',s).strip()
    full=[hashlib.md5(norm(c).encode()).hexdigest()[:6] for c in cs]
    pref=[hashlib.md5(norm(c)[:60].encode()).hexdigest()[:6] for c in cs]
    # max run of consecutive identical prefix
    def maxrun(seq):
        best=1;cur=1
        for i in range(1,len(seq)):
            if seq[i]==seq[i-1]: cur+=1; best=max(best,cur)
            else: cur=1
        return best
    from collections import Counter
    print(f'{t}: n={len(cs)} distinct_full={len(set(full))} distinct_pref60={len(set(pref))} maxrun_full={maxrun(full)} maxrun_pref60={maxrun(pref)} topprefcount={Counter(pref).most_common(1)}')
"
